npm install postmark 2>&1 | tail -3
cat > src/lib/postmark.ts <<'EOF'
import { ServerClient } from "postmark";

export const postmark = new ServerClient(process.env.POSTMARK_SERVER_TOKEN!);
EOF
cat > src/lib/email.ts <<'EOF'
import { postmark } from "@/lib/postmark";

type Message = { to: string; subject: string; html: string; text: string };

function escapeHtml(s: string) {
  return s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
}

// Failures are logged, not thrown, so a bad email never breaks the request that triggered it.
async function send({ to, subject, html, text }: Message) {
  try {
    await postmark.sendEmail({
      From: process.env.POSTMARK_FROM_EMAIL!,
      To: to,
      Subject: subject,
      HtmlBody: html,
      TextBody: text,
      MessageStream: "outbound",
    });
  } catch (err) {
    console.error("Failed to send email:", err);
  }
}

export function sendWelcomeEmail(user: { email: string; name: string }) {
  return send({
    to: user.email,
    subject: "Welcome to Notely",
    html: `<p>Hi ${escapeHtml(user.name)}, welcome to Notely!</p>`,
    text: `Hi ${user.name}, welcome to Notely!`,
  });
}

export function sendPasswordResetEmail(
  user: { email: string; name: string },
  resetUrl: string,
) {
  return send({
    to: user.email,
    subject: "Reset your Notely password",
    html: `<p>Hi ${escapeHtml(user.name)},</p><p><a href="${escapeHtml(resetUrl)}">Reset your password</a>. This link expires in 1 hour. If you didn't ask for this, ignore this email.</p>`,
    text: `Hi ${user.name},\n\nReset your password: ${resetUrl}\n\nThis link expires in 1 hour. If you didn't ask for this, ignore this email.`,
  });
}
EOF
cat >> src/lib/users.ts <<'EOF'

export async function createUser(input: { email: string; name: string }): Promise<User> {
  const user: User = {
    id: String(users.length + 1),
    email: input.email,
    name: input.name,
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  await sendWelcomeEmail(user);
  return user;
}

const RESET_TTL_MS = 60 * 60 * 1000;
// In-memory like the user list; stores a hash of each token, never the token itself.
const resetTokens = new Map<string, { userId: string; expires: number }>();

const hashToken = (token: string) => createHash("sha256").update(token).digest("hex");

// Resolves the same way whether or not the email exists, to avoid leaking accounts.
export async function requestPasswordReset(email: string): Promise<void> {
  const user = users.find((u) => u.email.toLowerCase() === email.toLowerCase());
  if (!user) return;
  const token = randomBytes(32).toString("hex");
  resetTokens.set(hashToken(token), { userId: user.id, expires: Date.now() + RESET_TTL_MS });
  const base = process.env.APP_URL ?? "http://localhost:3000";
  await sendPasswordResetEmail(user, `${base}/reset-password?token=${token}`);
}

// Returns the user a valid token belongs to and consumes it (single use).
export async function consumeResetToken(token: string): Promise<User | undefined> {
  const key = hashToken(token);
  const entry = resetTokens.get(key);
  resetTokens.delete(key);
  if (!entry || entry.expires < Date.now()) return undefined;
  return getUser(entry.userId);
}
EOF
